const http = require('http');
const { URL } = require('url');

function createApp() {
  const middlewares = [];
  const routes = [];

  function enhanceRes(res) {
    if (res._enhanced) return;
    res._enhanced = true;
    res.status = function status(code) {
      res.statusCode = code;
      return res;
    };
    res.json = function json(payload) {
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify(payload));
    };
    res.send = function send(payload) {
      if (typeof payload === 'object' && !Buffer.isBuffer(payload)) {
        return res.json(payload);
      }
      res.end(payload);
    };
  }

  function register(method, path, handlers) {
    routes.push({ method, path, handlers });
  }

  function matchRoute(method, pathname) {
    for (const route of routes) {
      if (route.method !== method) continue;
      const match = matchPath(route.path, pathname);
      if (match) {
        return { params: match, handlers: route.handlers };
      }
    }
    return null;
  }

  function handle(req, res) {
    enhanceRes(res);
    const parsedUrl = new URL(req.url, 'http://localhost');
    req.path = parsedUrl.pathname;
    req.query = Object.fromEntries(parsedUrl.searchParams.entries());
    req.params = {};
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
    });
    req.on('end', () => {
      if (body && req.headers['content-type'] && req.headers['content-type'].includes('application/json')) {
        try {
          req.body = body ? JSON.parse(body) : {};
        } catch (err) {
          res.status(400).json({ error: 'Invalid JSON' });
          return;
        }
      } else {
        req.body = body;
      }
      dispatch();
    });

    function dispatch() {
      const stack = [];
      middlewares.forEach((mw) => {
        const base = mw.path || '';
        const matches =
          !base ||
          base === '*' ||
          req.path === base ||
          req.path.startsWith(base.endsWith('/') ? base : `${base}/`);
        if (!matches) return;
        if (mw.isRouter) {
          stack.push((req, res, next) => {
            const originalUrl = req.url;
            const originalPath = req.path;
            if (base && base !== '*') {
              req.url = req.url.slice(base.length) || '/';
              req.path = req.path.slice(base.length) || '/';
              if (!req.url.startsWith('/')) req.url = `/${req.url}`;
              if (!req.path.startsWith('/')) req.path = `/${req.path}`;
            }
            mw.handler.handle(req, res, (err) => {
              req.url = originalUrl;
              req.path = originalPath;
              next(err);
            });
          });
        } else {
          stack.push(mw.handler);
        }
      });
      const route = matchRoute(req.method, req.path);
      if (route) {
        req.params = route.params;
        stack.push(...route.handlers);
      } else {
        stack.push((req, res) => res.status(404).json({ error: 'Not Found' }));
      }
      let idx = 0;
      function next(err) {
        const fn = stack[idx++];
        if (!fn) {
          if (err) {
            res.status(500).json({ error: err.message || 'Server error' });
          }
          return;
        }
        if (err) {
          if (fn.length === 4) {
            return fn(err, req, res, next);
          }
          return next(err);
        }
        if (fn.length <= 3) {
          try {
            fn(req, res, next);
          } catch (error) {
            next(error);
          }
        } else {
          next();
        }
      }
      next();
    }
  }

  const app = (req, res) => handle(req, res);

  app.use = function use(path, handler) {
    if (typeof path === 'function') {
      handler = path;
      path = null;
    }
    middlewares.push({ path: path || null, handler, isRouter: handler && handler._isRouter });
  };

  ['get', 'post', 'put', 'delete', 'patch'].forEach((method) => {
    app[method] = function registerRoute(path, ...handlers) {
      register(method.toUpperCase(), path, handlers);
    };
  });

  app.listen = function listen(port, cb) {
    const server = http.createServer(handle);
    return server.listen(port, cb);
  };

  app.handle = handle;
  return app;
}

function Router() {
  const router = createApp();
  router._isRouter = true;
  return router;
}

function matchPath(routePath, pathname) {
  if (routePath === pathname) {
    return {};
  }
  const routeParts = routePath.split('/').filter(Boolean);
  const pathParts = pathname.split('/').filter(Boolean);
  if (routeParts.length !== pathParts.length) {
    return null;
  }
  const params = {};
  for (let i = 0; i < routeParts.length; i++) {
    const routePart = routeParts[i];
    const pathPart = pathParts[i];
    if (routePart.startsWith(':')) {
      params[routePart.slice(1)] = decodeURIComponent(pathPart);
    } else if (routePart !== pathPart) {
      return null;
    }
  }
  return params;
}

createApp.Router = Router;
createApp.json = () => (req, res, next) => next();

module.exports = createApp;
